messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Low Poly Humanoid Animation</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #1a1a1a; }
        canvas { display: block; }
    </style>
</head>
<body>
<script type="module">
    import * as THREE from './three.module.js';

    // --- Configuration ---
    const CYCLE_DURATION = 10.0; // seconds
    const STANDING_TIME = 2.0;
    const WALKING_TIME = 3.0;
    const RUNNING_TIME = 3.0;

    // --- Scene Setup ---
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x222222);
    scene.fog = new THREE.Fog(0x222222, 10, 50);

    // Side-on camera
    const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 100);
    camera.position.set(0, 2, 8);
    camera.lookAt(0, 1.5, 0);

    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.shadowMap.enabled = true;
    document.body.appendChild(renderer.domElement);

    // --- Lighting ---
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
    scene.add(ambientLight);

    const dirLight = new THREE.DirectionalLight(0xffffff, 1);
    dirLight.position.set(5, 10, 7);
    dirLight.castShadow = true;
    scene.add(dirLight);

    // --- Materials ---
    const skinMat = new THREE.MeshStandardMaterial({ color: 0x3498db, flatShading: true }); // Blue
    const pantsMat = new THREE.MeshStandardMaterial({ color: 0x2c3e50, flatShading: true }); // Dark Blue
    const shoeMat = new THREE.MeshStandardMaterial({ color: 0xe74c3c, flatShading: true });  // Red
    const groundMat = new THREE.MeshStandardMaterial({ color: 0x555555, flatShading: true });

    // --- Character Construction (Hierarchical) ---

    // Helper to create low-poly cylinders
    function createLimb(radiusTop, radiusBottom, height, material, segments = 4) {
        const geo = new THREE.CylinderGeometry(radiusTop, radiusBottom, height, segments);
        geo.translate(0, height / 2, 0); // Pivot at bottom
        return new THREE.Mesh(geo, material);
    }

    // Root of the character
    const character = new THREE.Group();
    scene.add(character);

    // Hips (Root of body)
    const hips = new THREE.Group();
    hips.position.y = 1.0;
    character.add(hips);

    // Torso
    const torso = createLimb(0.15, 0.2, 0.6, skinMat);
    torso.position.y = 0.2; // Shift up relative to hips
    hips.add(torso);

    // Head
    const head = new THREE.Mesh(new THREE.DodecahedronGeometry(0.15), skinMat);
    head.position.y = 0.6;
    torso.add(head);

    // --- Arms ---
    // Left Arm
    const leftShoulder = new THREE.Group();
    leftShoulder.position.set(0.25, 0.5, 0); // Relative to torso
    torso.add(leftShoulder);
    const leftUpperArm = createLimb(0.06, 0.05, 0.3, skinMat);
    leftShoulder.add(leftUpperArm);
    const leftElbow = new THREE.Group();
    leftElbow.position.y = 0.3;
    leftUpperArm.add(leftElbow);
    const leftForearm = createLimb(0.05, 0.04, 0.3, skinMat);
    leftElbow.add(leftForearm);

    // Right Arm
    const rightShoulder = new THREE.Group();
    rightShoulder.position.set(-0.25, 0.5, 0);
    torso.add(rightShoulder);
    const rightUpperArm = createLimb(0.06, 0.05, 0.3, skinMat);
    rightShoulder.add(rightUpperArm);
    const rightElbow = new THREE.Group();
    rightElbow.position.y = 0.3;
    rightUpperArm.add(rightElbow);
    const rightForearm = createLimb(0.05, 0.04, 0.3, skinMat);
    rightElbow.add(rightForearm);

    // --- Legs ---
    // Left Leg
    const leftHip = new THREE.Group();
    leftHip.position.set(0.12, 0, 0); // Relative to hips
    hips.add(leftHip);
    const leftThigh = createLimb(0.08, 0.06, 0.4, pantsMat);
    leftHip.add(leftThigh);
    const leftKnee = new THREE.Group();
    leftKnee.position.y = 0.4;
    leftThigh.add(leftKnee);
    const leftShin = createLimb(0.06, 0.05, 0.4, pantsMat);
    leftKnee.add(leftShin);
    const leftFoot = createLimb(0.05, 0.04, 0.1, shoeMat);
    leftFoot.position.y = 0.4;
    leftKnee.add(leftFoot);

    // Right Leg
    const rightHip = new THREE.Group();
    rightHip.position.set(-0.12, 0, 0);
    hips.add(rightHip);
    const rightThigh = createLimb(0.08, 0.06, 0.4, pantsMat);
    rightHip.add(rightThigh);
    const rightKnee = new THREE.Group();
    rightKnee.position.y = 0.4;
    rightThigh.add(rightKnee);
    const rightShin = createLimb(0.06, 0.05, 0.4, pantsMat);
    rightKnee.add(rightShin);
    const rightFoot = createLimb(0.05, 0.04, 0.1, shoeMat);
    rightFoot.position.y = 0.4;
    rightKnee.add(rightFoot);

    // --- Environment (Treadmill) ---
    // Ground Plane
    const groundGeo = new THREE.PlaneGeometry(20, 10);
    const ground = new THREE.Mesh(groundGeo, groundMat);
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -0.01;
    ground.receiveShadow = true;
    scene.add(ground);

    // Treadmill Frame
    const frameGeo = new THREE.BoxGeometry(2, 0.5, 1.5);
    const frameMat = new THREE.MeshStandardMaterial({ color: 0x111111 });
    const treadmillFrame = new THREE.Mesh(frameGeo, frameMat);
    treadmillFrame.position.y = -0.25;
    scene.add(treadmillFrame);

    // Treadmill Belt (Moving texture simulation via geometry or just a visual cue)
    const beltGeo = new THREE.BoxGeometry(1.8, 0.05, 1.2);
    const beltMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
    const belt = new THREE.Mesh(beltGeo, beltMat);
    belt.position.y = 0;
    scene.add(belt);

    // --- Animation Logic ---

    // Helper for smooth transitions
    function lerp(start, end, t) {
        return start * (1 - t) + end * t;
    }

    // Limb State Object
    const limbs = {
        leftLeg: { hip: leftHip, knee: leftKnee },
        rightLeg: { hip: rightHip, knee: rightKnee },
        leftArm: { shoulder: leftShoulder, elbow: leftElbow },
        rightArm: { shoulder: rightShoulder, elbow: rightElbow },
        torso: torso,
        hips: hips
    };

    // Parameters for states
    const params = {
        idle: {
            legSwing: 0,
            kneeBend: 0.2, // Slight bend for natural look
            armSwing: 0,
            elbowBend: 0.2,
            torsoLean: 0,
            bounce: 0,
            speed: 0
        },
        walk: {
            legSwing: 0.5, // Radians
            kneeBend: 0.8,
            armSwing: 0.4,
            elbowBend: 0.5,
            torsoLean: 0,
            bounce: 0.05,
            speed: 1.0
        },
        run: {
            legSwing: 0.9,
            kneeBend: 1.2, // More knee lift
            armSwing: 0.7,
            elbowBend: 1.0, // Bent arms
            torsoLean: 0.2, // Forward lean
            bounce: 0.15,
            speed: 2.0
        }
    };

    function animate(time) {
        requestAnimationFrame(animate);

        // Normalize time to 0-10 cycle
        const cycleTime = time % CYCLE_DURATION;
        const seconds = cycleTime;

        // Determine Phase and Progress (0.0 to 1.0 within phase)
        let phase = 'idle';
        let phaseTime = 0;
        let nextPhase = 'idle';

        if (seconds < STANDING_TIME) {
            phase = 'idle';
            phaseTime = seconds / STANDING_TIME;
            nextPhase = 'walk';
        } else if (seconds < STANDING_TIME + WALKING_TIME) {
            phase = 'walk';
            phaseTime = (seconds - STANDING_TIME) / WALKING_TIME;
            nextPhase = 'run';
        } else {
            phase = 'run';
            phaseTime = (seconds - STANDING_TIME - WALKING_TIME) / RUNNING_TIME;
            nextPhase = 'idle';
        }

        // Smooth Transition Logic
        // We blend between current phase params and next phase params near the end of a phase
        let blendFactor = 0;
        if (phaseTime > 0.8) {
            // Last 20% of phase blends into next
            blendFactor = (phaseTime - 0.8) / 0.2;
        }

        const currentP = params[phase];
        const nextP = params[nextPhase];

        // Interpolated Values
        const legSwing = lerp(currentP.legSwing, nextP.legSwing, blendFactor);
        const kneeBend = lerp(currentP.kneeBend, nextP.kneeBend, blendFactor);
        const armSwing = lerp(currentP.armSwing, nextP.armSwing, blendFactor);
        const elbowBend = lerp(currentP.elbowBend, nextP.elbowBend, blendFactor);
        const torsoLean = lerp(currentP.torsoLean, nextP.torsoLean, blendFactor);
        const bounce = lerp(currentP.bounce, nextP.bounce, blendFactor);
        const speed = lerp(currentP.speed, nextP.speed, blendFactor);

        // Animation Cycle (Sine waves)
        // We use a continuous time variable for the sine waves so it doesn't reset abruptly
        const animTime = time * speed * 2.5; 

        // --- Limb Animation ---

        // Legs (Opposing)
        // Left Leg
        limbs.leftLeg.hip.rotation.x = Math.sin(animTime) * legSwing;
        limbs.leftLeg.knee.rotation.x = -Math.max(0, Math.sin(animTime + Math.PI/2)) * kneeBend; // Only bend when lifting

        // Right Leg (Offset by PI)
        limbs.rightLeg.hip.rotation.x = Math.sin(animTime + Math.PI) * legSwing;
        limbs.rightLeg.knee.rotation.x = -Math.max(0, Math.sin(animTime + Math.PI + Math.PI/2)) * kneeBend;

        // Arms (Opposing to legs)
        // Left Arm
        limbs.leftArm.shoulder.rotation.x = Math.sin(animTime + Math.PI) * armSwing;
        limbs.leftArm.elbow.rotation.x = -Math.max(0, Math.sin(animTime + Math.PI)) * elbowBend;

        // Right Arm
        limbs.rightArm.shoulder.rotation.x = Math.sin(animTime) * armSwing;
        limbs.rightArm.elbow.rotation.x = -Math.max(0, Math.sin(animTime)) * elbowBend;

        // --- Body Animation ---

        // Torso Lean
        limbs.torso.rotation.x = torsoLean;

        // Vertical Bounce (Bobbing)
        // Bounce happens twice per leg cycle (every step)
        const bob = Math.abs(Math.sin(animTime)) * bounce;
        character.position.y = bob;

        // Subtle rotation for balance
        character.rotation.y = Math.sin(animTime * 0.5) * 0.05;

        // --- Environment Animation ---
        // Move treadmill belt texture or visual cue
        // Since we don't have a texture, we can simulate motion by moving the belt mesh slightly or just a visual effect
        // Let's create a simple visual effect: a line on the belt moving
        // Actually, simpler: Just move the camera slightly to simulate treadmill vibration if running
        if (phase === 'run') {
            camera.position.x = (Math.random() - 0.5) * 0.02;
            camera.position.y = 2 + (Math.random() - 0.5) * 0.02;
        } else {
            camera.position.set(0, 2, 8);
        }

        renderer.render(scene, camera);
    }

    // Handle Resize
    window.addEventListener('resize', () => {
        camera.aspect = window.innerWidth / window.innerHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(window.innerWidth, window.innerHeight);
    });

    // Start Loop
    animate(0);

</script>
</body>
</html>
```
